<?php use App\Core\View;ob_start(); ?><h1>Painel</h1><?php if(!$subscribed): ?><p class="warning">Você ainda não possui uma assinatura ativa. A integração de pagamento sandbox será exibida aqui.</p><?php endif ?><div class="grid"><article><b><?=View::e((string)$stats['total'])?></b><br>Contatos</article><article><b><?=View::e((string)$stats['active'])?></b><br>Ativos</article></div><h2>Campanhas</h2><a class="btn" href="/campanhas/nova">Nova campanha</a><table><tr><th>Título</th><th>Status</th><th>Enviados</th><th>Ação</th></tr><?php foreach($campaigns as $c): ?><tr><td><?=View::e($c['title'])?></td><td><?=View::e($c['status'])?></td><td><?=View::e((string)$c['sent'])?> / <?=View::e((string)$c['recipients'])?></td><td><?php if($c['status']==='draft'): ?><form method="post" action="/campanhas/finalizar"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button>Finalizar</button></form><?php endif ?></td></tr><?php endforeach ?></table><?php $body=ob_get_clean();$title='Painel';require __DIR__.'/layout.php'; ?>
